import sys
from itertools import product

def read_ints():
    return map(int, sys.stdin.readline().split())

class Coordinate:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def distance(self, other):
        return abs(self.x - other.x) + abs(self.y - other.y)

def make_tour(points):
    # Using nearest neighbor algorithm to find optimal tour
    current_point = points[0]
    tour = [(current_point.x, current_point.y)]
    remaining_points = points[1:]

    while remaining_points:
        next_point = min(remaining_points, key=lambda point: point.distance(current_point))
        tour.append((next_point.x, next_point.y))
        remaining_points.remove(next_point)
        current_point = next_point

    return list(zip(tour, tour[1:]))

def solve(n, a):
    points = [Coordinate(x, y) for x, y in zip(a[:n], a[n:])]
    # Using product of tuples to compute all possible tours
    all_tours = list(product(points, repeat=n))

    distances = []
    for tour in all_tours:
        distance = 0
        for point1, point2 in zip(tour, tour[1:]):
            distance += point1.distance(point2)
        distances.append(distance)

    # Find the minimum of all possible tours using list comprehension and min function
    min_distance = min(distances)

    print(min_distance)
    closest_tours = [tour for tour, dist in zip(all_tours, distances) if dist == min_distance]
    for x, y in zip(*closest_tours):
        print(x, y)

def main():
    for _ in range(next(read_ints())):
        n = next(read_ints())
        a = list(read_ints())
        solve(n*2, a)

if __name__ == "__main__":
    main()
