            print("Invalid Input")
            continue

        # Find the greatest common divisor of all elements in both lists
        gcd_a = reduce(gcd, a)
        gcd_b = reduce(gcd, b)

        if sum(a) // gcd_a > sum(b) // gcd_b:
            print("Tsondu")
        elif sum(a) // gcd_a < sum(b) // gcd_b and m != 1:
            print("Tenzing")
        else:
            combinations = itertools.product(a, b)
            for x, y in combinations:
                if abs(x - y) % gcd_a == 0 and abs(x - y) % gcd_b == 0:
                    left_remaining = a[:]
                    right_remaining = b[:]
                    i = j = 0
                    while min(left_remaining + right_remaining) > 0:
                        if x < y:
                            current_difference = y - x
                        else:
                            current_difference = x - y

                        if current_difference >= gcd_a and sum(left_remaining) // gcd_a > 1 or len(b) == 1:
                            left_remaining[0] -= current_difference
                        elif current_difference >= gcd_b:

                            right_remaining.pop(0)
                        i = j + 1
                    break
            else:
                print("Draw")
            continue

