import math
def reduce(f, xs):
    if len(xs) <= 1:
        return xs[0] if xs else float("inf") 
    x = iter(xs)
    a = next(x)
    result = f(a, next(x))
    for b in x:
        result = f(result, b)
    return result
def gcd(a, b):
    while b != 0:
        (a, b) = (b, a % b)
    return abs(a)
