from collections import Counter, defaultdict, deque

def solve():
    N = int(sys.stdin.readline())
    robot_order = list(map(int, sys.stdin.readline().split()))

    counts = Counter(robot_order).values()

    def is_possible(counts):
        count_queue = deque(sorted(counts))
        while count_queue:
            front_count = count_queue.popleft()
            if not front_count:
                return False
            neighbors_count = count_queue
            for i in range(len(neighbors_count)):
                if neighbors_count[i] < front_count - 1:
                    neighbors_count.pop(i)
                    break
            for c in neighbors_count:
                if c == front_count - 1:
                    count_queue.append(c + 1)
        return True

    print('YES' if is_possible(counts) else 'NO')
