import sys

def count_chars(s):
    cnt_a = [0] * 3
    cnt_b = [0] * 3
    for i, char in enumerate(s):
        if char == 'a':
            for j in range(3):
                cnt_a[j] += (i >> j) & 1
        elif char == 'b':
            for j in range(3):
                cnt_b[j] += (i >> j) & 1
    return cnt_a, cnt_b

def solve(s):
    a_order = ''
    b_count = []
    c_count = []
    cnt_a, cnt_b = count_chars(s)
    max_idx = -1
    for i in range(max(len(cnt_a), len(cnt_b))):
        if i >= len(cnt_a):
            a_order += 'a'
            c_count.append(0)
        elif i >= len(cnt_b):
            b_count.append(0)
        else:
            if cnt_a[i] == 2 and cnt_b[i] in (1, 2):
                max_idx = i
            a_order += 'b' if cnt_a[i] < 2 else 'a'
    for i in range(max(len(cnt_a), len(cnt_b))):
        b_count.append(0)
        c_count.append(0)
    if b_count == c_count:
        return ':('
    if max_idx != -1 and (any(b <= a_order < chr(ord('b') + 1) * 20 for b in [''.join([c * k for k, c in zip(c_count, b_count)])))):
        return a_order + ''.join(b_count) + ''.join(c_count)
    else:
        return ':('

