    def reorder(s):
        stack1 = []
        stack2 = []
        for char in s:
            stack1.append(char)
            while stack2 and stack2[-1] == char:
                stack1.append(stack2.pop())
        return ''.join(stack1 + list(reversed(stack1)))

    output_list = []
    for string in input_data:
        odd_string = ''
        even_string = ''
        for idx, char in enumerate(string):
