        max_val = (
            sum(weights) * 2
            if (fire_count >= frost_count and weights[0] <= weights[frost_count])
            else sum(weights) * 2 + sum(weights[:frost_count])
        )

        # When fire count is less than frost count, iterate over all possibilities
        # This implementation follows a greedy approach by choosing pairs that maximize total weight
        for i in range(fire_count):
            j = fire_count + n - i - 2
            max_val = (
                max(max_val, (sum(weights[:i]) + weights[i] * 2 + weights[j]
                            + weights[n-frost_count-j-1]) * 2 - weights[fire_count+i] - weights[n-fire_count-1])
