                    current_multiple_i = d*n//prime
                    if current_multiple_i <= n and current_multiple_i not in current_multiple_set:
                        current_multiple_set.add(current_multiple_i)
                        permutation.append(current_multiple_i - last_element // d)
                        last_element = current_multiple_i
                last_element = (number - 1) // d * d
            while number % d == 0:
                num_elements_with_prime_factor_of_d -= 1
                current_multiple_set.clear()
                permutation.reverse()
                last_element *= d
                for el in permutation:
                    if el <= n and el not in current_multiple_set:
                        current_multiple_set.add(el)
                        permutations = [el * d, el]
                        number_new = next((new_number for new_number in range(multiple * d + 1, (multiple+2)*d+1) 
                                         if new_number not in current_multiple_set), -1)
                        if number_new != -1 and number_new <= n:
                            permutations.append(number_new)
                            permutation.extend(permutations[1:] + [permutations[0]])
                            return " "*10 + str(d)+'\n'+" ".join([str(x) for x in permutation])
                permutation = []
            while False in current_multiple_set:
                current_multiple_set.remove(False)
            permutation.reverse()
            last_element //= d
        if num_elements_with_prime_factor_of_d > res_d and len(permutation) == n-1:
            res_d += 1 + num_elements_with_prime_factor_of_d
            res_permutation = permutation+[n]
    return "".join([str(d)+'\n'+" ".join([str(x) for x in [2] + list(range(4,2*n,2))])+' ']*(res_d == float('inf') + (1 if res_d != float('inf') else 0)))

